SELECT EXISTS(
    SELECT 1
    FROM assets a
    WHERE a.id = #{assetId}
        AND a.company_id = #{companyId}
        AND a.is_deleted = FALSE
)

mapper.update:
UPDATE requests
SET asset_id = #{assetId},
    process_type_code = #{processTypeCode},
    title = #{title},
    content = #{content},
    updated_by = #{updatedBy}
WHERE id = #{id}
    AND company_id = #{companyId}
    AND requester_user_id = #{requesterUserId}
    AND status_code = 'DRAFT'

UPDATE requests
SET status_code = 'SUBMITTED',
    submitted_at = #{submittedAt},
    updated_by = #{updatedBy}
WHERE id = #{id}
    AND company_id = #{companyId}
    AND requester_user_id = #{requesterUserId}
    AND status_code = 'DRAFT'

UPDATE requests
SET status_code = 'WITHDRAWN',
    updated_by = #{updatedBy}
WHERE id = #{id}
    AND company_id = #{companyId}
    AND requester_user_id = #{requesterUserId}
    AND status_code = 'SUBMITTED'

UPDATE requests
SET status_code = 'APPROVED',
    updated_by = #{updatedBy}
WHERE id = #{id}
    AND company_id = #{companyId}
    AND status_code = 'SUBMITTED'

UPDATE requests
SET status_code = 'REJECTED',
    review_comment = #{reviewComment},
    updated_by = #{updatedBy}
WHERE id = #{id}
    AND company_id = #{companyId}
    AND status_code = 'SUBMITTED'

UPDATE requests
SET status_code = 'DRAFT',
    review_comment = #{reviewComment},
    updated_by = #{updatedBy}
WHERE id = #{id}
    AND company_id = #{companyId}
    AND status_code = 'SUBMITTED'
